//! 🧪️ Descriptor construction matches the independent serde enum receiver with exact original text funding.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_value::RetainedCloneGrant;
fn observe<T>(f:impl FnOnce()->T)->(T,usize,usize){let(v,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);(v,h.requested_bytes,h.released_bytes)}
fn run(caller:&mut OriginalJobFixtureCaller,g:RetainedCloneGrant,fuel:u64,births:&mut usize,releases:&mut usize,f:impl FnOnce(&mut StepContext<'_>)->Result<(),OriginalTurnFailure>){let(_,born,free)=observe(||caller.turn(g,|cx|cx.with_original_work_loan(fuel,1500,f)).unwrap());let p=caller.receipt();assert!(p.fits(g));assert_eq!((born,free),(p.retained_capacity_bytes,p.released_bytes));*births+=born;*releases+=free}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[test]
fn original_add_descriptor_matches_serde_all_kinds_under_quoted_work_and_exact_cancel_custody(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️descriptor.json")).unwrap();let stock=RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:128<<20,maximum_capacity_bytes:256<<20,maximum_release_bytes:512<<20,maximum_depth:4096};
 for row in fixture["cases"].as_array().unwrap(){for stop in [None,Some(0),Some(1),Some(3),Some(7)]{
  let((payload,expected,mut work),born,free)=observe(||{let value=&row["payload"];let text=|key|value.get(key).and_then(serde_json::Value::as_str).map(str::to_owned);let payload=AddWidget{kind:text("kind").unwrap(),neuron_kind:text("neuronKind"),x:None,y:None,label:text("label"),action:text("action"),format:text("format")};let expected=if row["expected"].is_null(){None}else{Some(serde_json::from_value::<WidgetDescriptor>(row["expected"].clone()).unwrap())};(payload,expected,FlowAddDescriptorWork::new())});let original=born-free;let mut caller=OriginalJobFixtureCaller::admit(OperationId(97146),Generation(17),stock,||Some(1000),1500,32768);let(mut births,mut releases)=(0,0);let mut actual=None;let mut failure=None;
  for call in 0..200{if stop==Some(call){break}let fuel=work.next_work_demand(&payload,stock.maximum_copy_bytes).map_or(1,|quote|quote.max(1));run(&mut caller,RetainedCloneGrant{maximum_items:0,..stock},fuel,&mut births,&mut releases,|cx|{assert!(work.step(&payload,cx)?.is_none());Ok(())});run(&mut caller,stock,fuel,&mut births,&mut releases,|cx|{match work.step(&payload,cx){Ok(output)=>actual=output,Err(error)=>failure=Some(error)}Ok(())});if actual.is_some()||failure.is_some(){break}}
  if let Some(actual)=actual.as_ref(){assert_eq!(format!("{actual:?}"),format!("{:?}",expected.as_ref().unwrap()))}if stop.is_none(){assert_eq!(actual.is_some(),expected.is_some(),"descriptor row {} produced no output, failure {:?}, phase state after 200 calls",row["name"],failure.as_ref().map(|error|format!("{error:?}")));assert_eq!(failure.is_some(),expected.is_none(),"descriptor row {} failure mismatch",row["name"])}
  if stop.is_some(){caller.cancel().cancel_now();let fuel=work.next_work_demand(&payload,stock.maximum_copy_bytes).map_or(1,|quote|quote.max(1));run(&mut caller,stock,fuel,&mut births,&mut releases,|cx|{assert!(work.step(&payload,cx)?.is_none());Ok(())});assert_eq!(caller.receipt(),Default::default());}
  work.begin_close();for _ in 0..100000{if work.terminal_is_empty(){break}let d=work.close_demands(4096).unwrap();run(&mut caller,grant(d),1,&mut births,&mut releases,|cx|cx.with_original_retirement(|cx|work.close_step(cx).map(|_|())))}assert!(work.terminal_is_empty());
  let mut original_values=semio_framework_value::retirement::controlled::ControlledRetirement::new(((payload,expected),(actual,failure))).unwrap_or_else(|_|unreachable!("actual descriptor input and output support owned retirement"));for _ in 0..100000{if original_values.terminal_is_empty(){break}let d=original_values.selected_demand(4096).unwrap();run(&mut caller,grant(d),1,&mut births,&mut releases,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|g|{let result=original_values.step(g);RetainedWorkOutcome{result,work:original_values.last_turn_work()}})?;Ok(())}))}assert!(original_values.terminal_is_empty());assert_eq!(original+births,releases);caller.retire(stock);
 }}
}
